	/*
     * @param	event CreateWishlistEvent
     */
    @EventHandler( payloadType=CreateWishlistEvent.class )
    public void handle( CreateWishlistEvent event) {
	    LOGGER.info("handling CreateWishlistEvent - " + event );
	    Wishlist entity = new Wishlist();
            entity.setWishlistId( event.getWishlistId() );
            entity.setName( event.getName() );
            entity.setAsPublic( event.getAsPublic() );
            entity.setCreatedAt( event.getCreatedAt() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllWishlist( entity );
    }

    /*
     * @param	event UpdateWishlistEvent
     */
    @EventHandler( payloadType=UpdateWishlistEvent.class )
    public void handle( UpdateWishlistEvent event) {
    	LOGGER.info("handling UpdateWishlistEvent - " + event );
    	
	    Wishlist entity = new Wishlist();
            entity.setWishlistId( event.getWishlistId() );
            entity.setName( event.getName() );
            entity.setAsPublic( event.getAsPublic() );
            entity.setCreatedAt( event.getCreatedAt() );
            entity.setCustomer( event.getCustomer() );
            entity.setItems( event.getItems() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindWishlist( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllWishlist( entity );        
    }
    
