    /**
     * Method to retrieve the Wishlist via an WishlistPrimaryKey.
     * @param 	id Long
     * @return 	Wishlist
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Wishlist handle( FindWishlistQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getWishlistId() );
    }
    
    /**
     * Method to retrieve a collection of all Wishlists
     *
     * @param	query	FindAllWishlistQuery 
     * @return 	List<Wishlist> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Wishlist> handle( FindAllWishlistQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindWishlist,
 * but only if the id matches
 *
 * @param		entity	Wishlist
 */
	protected void emitFindWishlist( Wishlist entity ) {
		LOGGER.info("handling emitFindWishlist" );
		
	    queryUpdateEmitter.emit(FindWishlistQuery.class,
	                            query -> query.getFilter().getWishlistId().equals(entity.getWishlistId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllWishlist
	 * 
	 * @param		entity	Wishlist
	 */
	protected void emitFindAllWishlist( Wishlist entity ) {
		LOGGER.info("handling emitFindAllWishlist" );
		
	    queryUpdateEmitter.emit(FindAllWishlistQuery.class,
	                            query -> true,
	                            entity);
	}

